<?php require_once '../includes/functions.php';require_user();verify_csrf();$id=(int)($_POST['place_id']??0);$s=$pdo->prepare('SELECT id FROM favorites WHERE user_id=? AND place_id=?');$s->execute([user()['id'],$id]);if($s->fetch()){$pdo->prepare('DELETE FROM favorites WHERE user_id=? AND place_id=?')->execute([user()['id'],$id]);}else{$pdo->prepare('INSERT IGNORE INTO favorites(user_id,place_id) VALUES(?,?)')->execute([user()['id'],$id]);}header('Location: '.($_SERVER['HTTP_REFERER']??url('user/favorites.php')));exit;?>